$ErrorActionPreference = 'SilentlyContinue'
Get-ChildItem -Directory -Force | ForEach-Object {
  $sum = (Get-ChildItem $_.FullName -Recurse -Force -ErrorAction SilentlyContinue |
    Measure-Object -Property Length -Sum).Sum
  [PSCustomObject]@{
    Name = $_.Name
    MB   = [math]::Round(($sum / 1MB), 1)
  }
} | Sort-Object MB -Descending | Select-Object -First 15 | Format-Table -AutoSize

$repo = 'C:\Users\win\Desktop\Agent Platform'
$lock = Join-Path $repo '.git\index.lock'
$procs = Get-CimInstance Win32_Process -Filter "Name='git.exe'" |
  Where-Object { $_.CommandLine -and $_.CommandLine -like "*Agent Platform*" }
if ($procs) {
  Write-Host "Active git on Agent Platform:"
  $procs | Select-Object ProcessId, CommandLine | Format-List
  exit 1
}
if (Test-Path $lock) {
  Remove-Item -LiteralPath $lock -Force
  Write-Host "Removed stale index.lock"
} else {
  Write-Host "No lock file"
}
